inline bool IsCanonicalQuest351B(QuestId id) {
 return (id.value & 0xFFFF0000u)==kCanonicalNamespace351B;
}
inline const Entry351B* FindCanonicalQuest351B(QuestId id) {
 if(!IsCanonicalQuest351B(id)) return 0;
 std::size_t count=0; const Entry351B* all=AllEntries351B(count);
 const std::uint32_t ordinal=id.value & 0xFFFFu;
 if(ordinal==0u || ordinal>count) return 0;
 const Entry351B* candidate=&all[ordinal-1u];
 return candidate->id==id.value ? candidate : 0;
}
inline int Kind351B(const Entry351B& e) {
 const char c=e.category[0];
 return c=='p'? kProgressionKind351B:
        c=='d'? kDailyKind351B:
        c=='a'? kAlineKind351B:kWeeklyKind351B;
}
inline bool TryGetCanonicalDefinition351B(QuestId id, QuestDefinition& out) {
 const Entry351B* e=FindCanonicalQuest351B(id); if(!e)return false;
 QuestDefinition d; d.id=id;d.kind=Kind351B(*e);d.type=0;d.partyFlag=0;
 out=d;return true;
}
// Read-only V2 catalogue until old and new state machines have parity.
// This guard must be checked BEFORE handing any virtual ID to QuestDB.
inline bool MayExecuteCanonical351B(QuestId) {return false;}
